// Kiểm tra ngầm tài khoản + mật khẩu khi người dùng ngừng gõ (để nút đăng nhập "đứng yên" khi đúng).
// Không tạo phiên. Giới hạn riêng 40 lần / 15 phút cho mỗi tài khoản; quá giới hạn trả 'khoa' (khi đó nút cho bấm, dangNhap tự kiểm tra như thường).
function kiemTraTK(u, mk) {
  u = chuanTen_(u); mk = String(mk || '');
  if (!u || !mk) return false;
  var cache = CacheService.getScriptCache(), k = 'chk_' + u, n = +(cache.get(k) || 0);
  if (n >= 40 || +(cache.get('sai_' + u) || 0) >= 5) return 'khoa';
  var f = timUser_(u), ok = false;
  if (conHieuLuc_(f)) {
    var d = String(f.v[3] || '');
    if (d && d !== MK_AN) ok = d === mk;
    else if (f.v[7]) ok = bam_(String(f.v[6]), mk) === String(f.v[7]);
  }
  if (!ok) { cache.put(k, String(n + 1), 900); Utilities.sleep(300); }
  return ok;
}
